#nullable enable // autogenerated

using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.hellChariot_DeathEffects)]
    public class HellChariot_DeathEffects : AIEntityBehaviour, IDeathEffectsBehaviour
    {
        public HellChariot_DeathEffects(string nsp, string name) : base(nsp, name)
        {
        }
        public void DeathEffects(Entity entity, DeathInfo info)
        {
            var anubisandOffset = ANUBISAND_OFFSET;
            anubisandOffset.x *= entity.GetFacingX();
            entity.SpawnWithParams(VanillaEnemyID.anubisand, entity.Position + anubisandOffset);
        }
        public static readonly Vector3 ANUBISAND_OFFSET = new Vector3(-48, 32, 0);
    }
}
